//! MLX-backed runtime target for MLPL (Saga 14, Apple Silicon).
//!
//! Sibling to `mlpl-rt`. Exposes the same primitive surface --
//! `matmul`, `add`/`sub`/`mul`/`div`/`neg`, `exp`/`log`/`tanh`/
//! `sigmoid`/`relu`, `reshape`/`transpose` -- but dispatches
//! through Apple's MLX library via `mlx-rs`. A program compiled
//! against `mlpl-rt::<op>` must be swappable for `mlpl_mlx_rt::<op>`
//! without source changes; outputs agree bit-for-bit where the
//! two runtimes share a dtype, and within a documented fp32
//! tolerance where MLX downcasts to f32 for GPU dispatch.
//!
//! MLX-backed code lives behind three conditions at once:
//!
//! 1. the `mlx` Cargo feature (opt-in, off by default),
//! 2. `target_os = "macos"`,
//! 3. `target_arch = "aarch64"`.
//!
//! On any host that fails any of those, the crate still builds
//! but exports no primitives -- the CPU path in `mlpl-rt` remains
//! authoritative. The Saga 14 plan treats cross-platform CI as an
//! invariant, not a per-step concern; this gating is how we honor
//! it.
//!
//! Phase 1 grows the primitive surface across three steps:
//! step 001 introduced `matmul`; step 002 added the elementwise,
//! unary-activation, and shape ops listed above; step 003 closes
//! the forward-pass gap with reductions, softmax/log_softmax, and
//! cross_entropy. Each primitive lives in its own module so the
//! crate stays under the sw-checklist function-count budget as
//! the surface expands.

pub use mlpl_array::{ArrayError, DenseArray, Shape};
pub use mlpl_core::LabeledShape;

#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
mod activations;
#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
mod common;
#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
mod elementwise;
#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
mod matmul;
#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
mod reductions;
#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
mod shapes;

#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
pub use activations::{exp, log, relu, sigmoid, tanh};
#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
pub use elementwise::{add, div, mul, neg, sub};
#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
pub use matmul::matmul;
#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
pub use reductions::{argmax, cross_entropy, log_softmax, mean, reduce_mul, softmax};
#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
pub use shapes::{reshape, transpose};

// Conversion helpers + the MLX array type, re-exported so a higher
// crate (mlpl-eval's MLX LoRA path) can move weights in/out as
// `mlx_rs::Array` without depending on mlx-rs directly.
#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
pub use common::{dense_to_mlx, mlx_to_dense_data};
#[cfg(all(target_os = "macos", target_arch = "aarch64", feature = "mlx"))]
pub use mlx_rs::Array;
=== Cargo.toml ===
[package]
# Saga R1 step 001: renamed from `mlpl-mlx`. The
# crate is now the FFI shim only; the long-running
# MLX service binary lives in `mlpl-mlx-serve`.
name = "mlpl-mlx-rt"
edition.workspace = true
license.workspace = true
version.workspace = true

[features]
default = []
# Apple Silicon only. The `cfg(all(target_os = "macos", target_arch =
# "aarch64"))` guard inside the crate keeps the feature compilable on
# non-Apple hosts (where `mlx-rs`' C++/Metal toolchain would fail to
# build), making `cargo test -p mlpl-mlx-rt --features mlx` safe to run
# from a Linux CI host: it stubs out to a no-op surface.
mlx = ["dep:mlx-rs"]

[dependencies]
mlpl-array = { path = "../../../array/crates/mlpl-array" }
mlpl-array-ops-matmul = { path = "../../../array-compose/crates/mlpl-array-ops-matmul" }
mlpl-array-ops-shape = { path = "../../../array-element/crates/mlpl-array-ops-shape" }
mlpl-core = { path = "../../../types/crates/mlpl-core" }

# Pinned by Saga 14 plan (risk/mitigation item): upstream ABI can
# shift between minor versions. Bump deliberately, not transitively.
#
# `default-features = false` drops the `metal` feature so mlx-sys
# does not require the `metal` shader compiler (ships only with a
# full Xcode.app, not the Command Line Tools). We keep
# `accelerate` on -- that's Apple's CPU/SIMD BLAS, which is all
# Saga 14 step 001 needs to prove the crate integrates. A later
# step re-enables `metal` behind its own cfg gate once the Xcode
# dependency is documented in the project bootstrap.
mlx-rs = { version = "=0.25.3", optional = true, default-features = false, features = [
  "accelerate",
] }

[dev-dependencies]
# Saga 14 step 002: parity tests compare MLX outputs against the
# CPU path in `mlpl-rt`. Dev-only so `mlpl-mlx-rt` itself stays
# decoupled from the CPU runtime crate at link time.
mlpl-rt = { path = "../mlpl-rt" }

