    let as_f32 = raw
        .as_type::<f32>()
        .expect("argmax result casts to f32 for f64 round trip");
    let (out_dims, labels) = match axis {
        Some(ax) => drop_axis(a, ax),
        None => (vec![], None),
    };
    finalize(Shape::new(out_dims), mlx_to_dense_data(as_f32), labels)
