//! CUDA-backed runtime target for MLPL -- the candle analog of
//! `mlpl-mlx-rt`. Exposes the same core primitive surface
//! (`matmul`, `add`/`sub`/`mul`/`div`/`neg`, `reshape`/`transpose`)
//! but dispatches through candle's CUDA backend. A program compiled
//! against `mlpl-rt::<op>` is swappable for `mlpl_cuda_rt::<op>`;
//! outputs agree within a documented fp32 tolerance (candle
//! computes in f32 on the GPU, the CPU path stays f64).
//!
//! The nn surface (activations, reductions, softmax, cross_entropy)
//! lives in the sibling crate `mlpl-cuda-nn`.
//!
//! CUDA code is triple-gated: the `cuda` Cargo feature, plus
//! `target_os = "linux"` and `target_arch = "x86_64"`. On any host
//! that fails a gate the crate still builds but exports no
//! primitives -- the CPU path in `mlpl-rt` remains authoritative.
//!
//! This file is a FACADE (CLAUDE.md): behavior lives in named files.

pub use mlpl_array::{ArrayError, DenseArray, Shape};

#[cfg(all(feature = "cuda", target_os = "linux", target_arch = "x86_64"))]
mod common;
#[cfg(all(feature = "cuda", target_os = "linux", target_arch = "x86_64"))]
mod device;
#[cfg(all(feature = "cuda", target_os = "linux", target_arch = "x86_64"))]
mod elementwise;
#[cfg(all(feature = "cuda", target_os = "linux", target_arch = "x86_64"))]
mod tensor;

#[cfg(all(feature = "cuda", target_os = "linux", target_arch = "x86_64"))]
pub use elementwise::{add, div, mul, neg, sub};
#[cfg(all(feature = "cuda", target_os = "linux", target_arch = "x86_64"))]
pub use tensor::{matmul, reshape, transpose};

// Conversion helpers + the candle device, re-exported so higher
// crates (mlpl-cuda-nn, mlpl-eval's CUDA path) can move weights in
// and out as candle `Tensor`s and share the single CUDA device.
#[cfg(all(feature = "cuda", target_os = "linux", target_arch = "x86_64"))]
pub use common::{cuda_to_dense_data, dense_to_cuda, finalize};
#[cfg(all(feature = "cuda", target_os = "linux", target_arch = "x86_64"))]
pub use device::cuda_device;

