//! CUDA-backed elementwise primitives. Signatures mirror
//! `mlpl-rt`: binary ops take two `&DenseArray` and return
//! `Result<DenseArray, ArrayError>` with scalar broadcasting; `neg`
//! is an infallible unary map. candle's `broadcast_*` ops handle
//! both the same-shape and scalar-broadcast cases the CPU path
//! allows; shape/label resolution + dispatch go through
//! `common::binary`.

use crate::common::{binary, cuda_to_dense_data, dense_to_cuda};
use mlpl_array::{ArrayError, DenseArray};

/// Elementwise `a + b` with scalar broadcasting.
pub fn add(a: &DenseArray, b: &DenseArray) -> Result<DenseArray, ArrayError> {
    binary(a, b, |x, y| {
        x.broadcast_add(y).expect("cuda add on validated shapes")
    })
}

/// Elementwise `a - b` with scalar broadcasting.
pub fn sub(a: &DenseArray, b: &DenseArray) -> Result<DenseArray, ArrayError> {
    binary(a, b, |x, y| {
        x.broadcast_sub(y).expect("cuda sub on validated shapes")
    })
}

/// Elementwise `a * b` (Hadamard) with scalar broadcasting.
pub fn mul(a: &DenseArray, b: &DenseArray) -> Result<DenseArray, ArrayError> {
    binary(a, b, |x, y| {
        x.broadcast_mul(y).expect("cuda mul on validated shapes")
    })
}

/// Elementwise `a / b` with scalar broadcasting.
pub fn div(a: &DenseArray, b: &DenseArray) -> Result<DenseArray, ArrayError> {
    binary(a, b, |x, y| {
        x.broadcast_div(y).expect("cuda div on validated shapes")
    })
}

/// Unary elementwise negation. Infallible: shape and labels pass
/// through from `a`.
#[must_use]
pub fn neg(a: &DenseArray) -> DenseArray {
    let t = dense_to_cuda(a.data(), a.shape().dims());
    let r = t.affine(-1.0, 0.0).expect("cuda neg on validated shape");
    let array = DenseArray::new(a.shape().clone(), cuda_to_dense_data(&r))
        .expect("output element count matches input");
    match a.labels() {
        Some(lbls) => array
            .with_labels(lbls.to_vec())
            .expect("labels already validated on input"),
        None => array,
    }
}

