//! CUDA-backed matmul + shape primitives. Shapes are validated on
//! the Rust side so candle sees only legal inputs; label
//! propagation mirrors `mlpl-array` (matmul: contraction labels
//! must agree; reshape drops labels; transpose reverses them).

use crate::common::{cuda_to_dense_data, dense_to_cuda, finalize};
use mlpl_array::{ArrayError, DenseArray, Shape};
use mlpl_array_ops_shape::prelude::*;

/// Matrix multiply backed by candle. Shape rules match the CPU path:
/// `[m, k] @ [k, n] -> [m, n]` and `[m, k] @ [k] -> [m]`.
///
/// # Errors
/// `RankMismatch` if `a` is not rank 2; `ShapeMismatch` if `b`'s
/// leading dim does not match `a`'s `k`; `LabelMismatch` on
/// disagreeing contraction labels.
pub fn matmul(a: &DenseArray, b: &DenseArray) -> Result<DenseArray, ArrayError> {
    let (m, k) = match a.shape().dims() {
        [m, k] => (*m, *k),
        _ => {
            return Err(ArrayError::RankMismatch {
                expected: 2,
                got: a.rank(),
            });
        }
    };
    let result_labels = matmul_labels(a, b)?;
    match b.shape().dims() {
        [k2, n] if *k2 == k => {
            let n = *n;
            let data = compute(a.data(), b.data(), &[m, k], &[k, n]);
            finalize(Shape::new(vec![m, n]), data, result_labels)
        }
        [k2] if *k2 == k => {
            let data = compute(a.data(), b.data(), &[m, k], &[k]);
            finalize(Shape::vector(m), data, result_labels)
        }
        _ => Err(ArrayError::ShapeMismatch {
            source: k,
            target: b.shape().dims().first().copied().unwrap_or(0),
        }),
    }
}

/// Run the candle matmul on two shape-validated f64 buffers. candle
/// needs 2D operands, so a matrix-vector product reshapes the
/// vector to `[k, 1]` and flattens the `[m, 1]` result back to `[m]`.
fn compute(a: &[f64], b: &[f64], a_dims: &[usize], b_dims: &[usize]) -> Vec<f64> {
    let at = dense_to_cuda(a, a_dims);
    let bt = dense_to_cuda(b, b_dims);
    let c = if b_dims.len() == 1 {
        let b2 = bt.reshape((b_dims[0], 1)).expect("reshape vec operand");
        let prod = at.matmul(&b2).expect("cuda matmul (matrix-vector)");
        prod.reshape((a_dims[0],)).expect("flatten matmul result")
    } else {
        at.matmul(&bt).expect("cuda matmul (matrix-matrix)")
    };
    cuda_to_dense_data(&c)
}

/// `reshape(a, dims)` -- reinterpret with new dims. Element count
/// must match. Labels drop, matching the CPU path.
///
/// # Errors
/// `ShapeMismatch` if the element count differs from `dims`'s product.
pub fn reshape(a: &DenseArray, dims: &[usize]) -> Result<DenseArray, ArrayError> {
    let source = a.elem_count();
    let target: usize = dims.iter().product();
    if source != target {
        return Err(ArrayError::ShapeMismatch { source, target });
    }
    let t = dense_to_cuda(a.data(), a.shape().dims());
    let r = t.reshape(dims.to_vec()).expect("cuda reshape on validated count");
    finalize(Shape::new(dims.to_vec()), cuda_to_dense_data(&r), None)
}

/// `transpose(a)` -- reverse axis order, reorder data to row-major,
/// reverse labels. Delegates to the CPU stride walk (cheap at these
/// sizes); candle transpose is a strided view whose flat readback
/// would not match without an explicit contiguous copy.
#[must_use]
pub fn transpose(a: &DenseArray) -> DenseArray {
    a.transpose()
}

/// Mirror of `mlpl-array`'s private `matmul_labels`: contraction
/// labels must agree; survivors are `[a.labels[0], b.labels[1]]`.
fn matmul_labels(
    a: &DenseArray,
    b: &DenseArray,
) -> Result<Option<Vec<Option<String>>>, ArrayError> {
    if a.labels().is_none() && b.labels().is_none() {
        return Ok(None);
    }
    let default_b = vec![None; b.rank()];
    let al: &[Option<String>] = a.labels().unwrap_or(&[None, None][..]);
    let bl: &[Option<String>] = b.labels().unwrap_or(default_b.as_slice());
    if let (Some(sa), Some(sb)) = (&al[1], &bl[0])
        && sa != sb
    {
        return Err(ArrayError::LabelMismatch {
            expected: al.to_vec(),
            actual: bl.to_vec(),
        });
    }
    let mut result = vec![al[0].clone()];
    if b.rank() == 2 {
        result.push(bl[1].clone());
    }
    Ok(Some(result))
}

