83	        let arr = env
84	            .peer_dispatcher()
85	            .ok_or_else(|| EvalError::Unsupported("to_device: no peer dispatcher".into()))?
86	            .fetch_tensor(&peer, &handle)?;
87	        if let Expr::Ident(name, _) = value_expr {
88	            env.set(name.clone(), arr.clone());
89	            env.remove_device_tensor(name);
90	            env.set_tensor_device(name.clone(), "cpu".into());
91	        }
92	        return Ok(Value::Array(arr));
93	    }
94	    if let Expr::Ident(name, _) = value_expr {
95	        env.set_tensor_device(name.clone(), "cpu".into());
96	    }
97	    value.into_array().map(Value::Array)
98	}
99	
100	/// Stamp `target` onto an identifier binding so downstream `apply`
101	/// sees it. When the name resolves to a model, stamp every param and
102	/// return `Some(scalar zero)` (a model has no single array value);
103	/// otherwise stamp the binding and return `None`.
104	fn stamp_target(target: &str, value_expr: &Expr, env: &mut Environment) -> Option<Value> {
105	    let Expr::Ident(name, _) = value_expr else {
106	        return None;
107	    };
108	    let params = env
109	        .get_model(name)
110	        .map(mlpl_eval_core::model::ModelSpec::params);
111	    if let Some(params) = params {
112	        for p in params {
113	            env.set_tensor_device(p, target.to_string());
114	        }
115	        return Some(Value::Array(DenseArray::from_scalar(0.0)));
116	    }
117	    env.set_tensor_device(name.clone(), target.to_string());
118	    None
119	}
